CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(128) NOT NULL, username VARCHAR(128) NOT NULL, password_hash VARCHAR(255) NOT NULL, balance DECIMAL(13, 2) NOT NULL);
ALTER TABLE users ADD CONSTRAINT users_email_unique UNIQUE (email);
CREATE TABLE IF NOT EXISTS categories (id INT AUTO_INCREMENT PRIMARY KEY, `name` VARCHAR(128) NOT NULL, image VARCHAR(255) NOT NULL, color VARCHAR(7) NOT NULL, user_id INT NULL, CONSTRAINT fk_categories_user_id__id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE categories ADD CONSTRAINT categories_name_user_id_unique UNIQUE (`name`, user_id);
CREATE TABLE IF NOT EXISTS costs (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(128) NOT NULL, description VARCHAR(255) NOT NULL, category_id INT NOT NULL, `value` DECIMAL(13, 2) NOT NULL, `type` VARCHAR(10) NOT NULL, CONSTRAINT fk_costs_user_id__id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_costs_category_id__id FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_cost_value_non_negative CHECK (`value` >= 0));
CREATE TABLE IF NOT EXISTS refresh_tokens (id INT AUTO_INCREMENT PRIMARY KEY, token_hash VARCHAR(64) NOT NULL, user_id INT NOT NULL, family_id VARCHAR(36) NOT NULL, expires_at BIGINT NOT NULL, revoked BOOLEAN DEFAULT FALSE NOT NULL, CONSTRAINT fk_refresh_tokens_user_id__id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE refresh_tokens ADD CONSTRAINT refresh_tokens_token_hash_unique UNIQUE (token_hash)